I wrote a `ChatRoom` Durable Object backed by SQLite, with one instance per room. It serializes writes by doing each one as a synchronous `transactionSync` and arms an hourly alarm that re-schedules itself. I didn't run it or call any Cloudflare tools, and the hourly job (deleting messages older than 7 days) is a placeholder for whatever you want to run.

```typescript
import { DurableObject } from "cloudflare:workers";

export interface Env {
  CHAT_ROOM: DurableObjectNamespace<ChatRoom>;
}

const HOUR_MS = 60 * 60 * 1000;

export interface Message {
  id: number;
  author: string;
  body: string;
  ts: number;
}

export class ChatRoom extends DurableObject<Env> {
  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      this.ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS messages (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          author TEXT NOT NULL,
          body TEXT NOT NULL,
          ts INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS meta (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL
        );
      `);
      // Make sure the hourly alarm exists. setAlarm replaces any existing one,
      // so only set it when none is pending.
      if ((await this.ctx.storage.getAlarm()) === null) {
        await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
      }
    });
  }

  // Writes are serialized: each RPC runs to completion before the next one
  // starts, and the SQL calls are synchronous with no awaits between them.
  // transactionSync makes the multi-statement write atomic.
  async postMessage(author: string, body: string): Promise<Message> {
    const ts = Date.now();
    return this.ctx.storage.transactionSync(() => {
      const { id } = this.ctx.storage.sql
        .exec<{ id: number }>(
          "INSERT INTO messages (author, body, ts) VALUES (?, ?, ?) RETURNING id",
          author,
          body,
          ts,
        )
        .one();
      this.ctx.storage.sql.exec(
        "INSERT INTO meta (key, value) VALUES ('last_message_ts', ?) " +
          "ON CONFLICT(key) DO UPDATE SET value = excluded.value",
        String(ts),
      );
      return { id, author, body, ts };
    });
  }

  async getMessages(limit = 50): Promise<Message[]> {
    return this.ctx.storage.sql
      .exec<Message>(
        "SELECT id, author, body, ts FROM messages ORDER BY id DESC LIMIT ?",
        limit,
      )
      .toArray()
      .reverse();
  }

  // Runs once an hour. If this throws, the runtime retries it with backoff,
  // so the work should be idempotent.
  async alarm(): Promise<void> {
    const cutoff = Date.now() - 24 * HOUR_MS;
    this.ctx.storage.sql.exec("DELETE FROM messages WHERE ts < ?", cutoff);
    this.ctx.storage.sql.exec(
      "INSERT INTO meta (key, value) VALUES ('last_swept', ?) " +
        "ON CONFLICT(key) DO UPDATE SET value = excluded.value",
      String(Date.now()),
    );
    await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
  }
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const room = new URL(request.url).searchParams.get("room") ?? "lobby";
    const stub = env.CHAT_ROOM.getByName(room);
    if (request.method === "POST") {
      const { author, body } = await request.json<{ author: string; body: string }>();
      return Response.json(await stub.postMessage(author, body));
    }
    return Response.json(await stub.getMessages());
  },
};
