```ts
import { DurableObject } from "cloudflare:workers";

const HOUR_MS = 60 * 60 * 1000;

export interface Env {
  CHAT_ROOM: DurableObjectNamespace<ChatRoom>;
}

export class ChatRoom extends DurableObject<Env> {
  private writeQueue: Promise<unknown> = Promise.resolve();

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS room_state (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL,
          updated_at INTEGER NOT NULL
        )
      `);
      // setAlarm replaces any existing alarm, so only arm one when none is set.
      const next = await ctx.storage.getAlarm();
      if (next === null) {
        await ctx.storage.setAlarm(Date.now() + HOUR_MS);
      }
    });
  }

  // Runs each write after the previous one settles. A failed write does not
  // block the queue.
  private enqueue<T>(work: () => T | Promise<T>): Promise<T> {
    const run = this.writeQueue.then(() => work());
    this.writeQueue = run.catch(() => {});
    return run;
  }

  private readState(key: string): string | null {
    const rows = this.ctx.storage.sql
      .exec<{ value: string }>("SELECT value FROM room_state WHERE key = ?", key)
      .toArray();
    return rows[0]?.value ?? null;
  }

  private writeState(key: string, value: string): void {
    this.ctx.storage.sql.exec(
      `INSERT INTO room_state (key, value, updated_at) VALUES (?, ?, ?)
       ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`,
      key,
      value,
      Date.now(),
    );
  }

  async setState(key: string, value: string): Promise<void> {
    await this.enqueue(() => this.writeState(key, value));
  }

  async getState(key: string): Promise<string | null> {
    return this.readState(key);
  }

  // Read-modify-write where the new value comes from awaited external I/O.
  // The queue keeps other writes from landing between the read and the write.
  async updateWithIO(
    key: string,
    compute: (current: string | null) => Promise<string>,
  ): Promise<string> {
    return this.enqueue(async () => {
      const next = await compute(this.readState(key));
      this.writeState(key, next);
      return next;
    });
  }

  async alarm(): Promise<void> {
    await this.enqueue(() => this.writeState("last_tick_at", String(Date.now())));
    // Reschedule last. If the tick throws, the alarm retries instead of stopping.
    await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
  }
}
```

