```typescript
import { DurableObject } from "cloudflare:workers";

const HOUR_MS = 60 * 60 * 1000;

export interface Env {
  CHAT_ROOM: DurableObjectNamespace<ChatRoom>;
}

export interface Message {
  id: number;
  author: string;
  body: string;
  sentAt: number;
}

export class ChatRoom extends DurableObject<Env> {
  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      this.ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS messages (
          id      INTEGER PRIMARY KEY AUTOINCREMENT,
          author  TEXT    NOT NULL,
          body    TEXT    NOT NULL,
          sent_at INTEGER NOT NULL
        )
      `);
      if ((await this.ctx.storage.getAlarm()) === null) {
        await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
      }
    });
  }

  // Synchronous SQL with no await between statements, so each call commits atomically
  // and the DO's input gate runs calls one at a time.
  async postMessage(author: string, body: string): Promise<Message> {
    const sentAt = Date.now();
    const row = this.ctx.storage.sql
      .exec<{ id: number }>(
        "INSERT INTO messages (author, body, sent_at) VALUES (?, ?, ?) RETURNING id",
        author,
        body,
        sentAt,
      )
      .one();
    return { id: row.id, author, body, sentAt };
  }

  async history(limit = 50): Promise<Message[]> {
    return this.ctx.storage.sql
      .exec<{ id: number; author: string; body: string; sent_at: number }>(
        "SELECT id, author, body, sent_at FROM messages ORDER BY id DESC LIMIT ?",
        limit,
      )
      .toArray()
      .reverse()
      .map((r) => ({ id: r.id, author: r.author, body: r.body, sentAt: r.sent_at }));
  }

  async alarm(): Promise<void> {
    // Hourly housekeeping: drop messages older than 30 days.
    this.ctx.storage.sql.exec(
      "DELETE FROM messages WHERE sent_at < ?",
      Date.now() - 30 * 24 * HOUR_MS,
    );
    await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
  }
}
```

