    return this.ctx.storage.sql
      .exec<ChatMessage>(
        "INSERT INTO messages (author, body, sent_at) VALUES (?, ?, ?) RETURNING *",
        author,
        body,
        Date.now(),
      )
      .one();
  }

  async getMessages(limit = 50, beforeId?: number): Promise<ChatMessage[]> {
    const rows = beforeId === undefined
      ? this.ctx.storage.sql.exec<ChatMessage>(
          "SELECT * FROM messages ORDER BY id DESC LIMIT ?", limit)
      : this.ctx.storage.sql.exec<ChatMessage>(
          "SELECT * FROM messages WHERE id < ? ORDER BY id DESC LIMIT ?", beforeId, limit);
